package aws

import "github.com/rusik69/lc/internal/problems"

func init() {
	problems.RegisterAWSQuestions([]problems.Question{
		{ID: 1, Text: "What is AWS?", Options: [4]string{"Amazon Web Services", "Cloud platform", "IaaS/PaaS/SaaS", "All of the above"}, CorrectAnswer: 3, Explanation: "AWS (Amazon Web Services) is Amazon's comprehensive cloud computing platform. Provides Infrastructure as a Service (IaaS), Platform as a Service (PaaS), and Software as a Service (SaaS). Offers 200+ services including compute, storage, databases, networking, analytics, AI/ML. Largest cloud provider globally. Pay-as-you-go pricing model."},
		{ID: 2, Text: "What is EC2?", Options: [4]string{"Elastic Compute Cloud", "Virtual servers", "Scalable compute", "All of the above"}, CorrectAnswer: 3, Explanation: "EC2 (Elastic Compute Cloud) provides resizable virtual servers in the cloud. Choose instance types, operating systems, storage. Scale up/down based on demand. Pay only for what you use. Core AWS compute service. Supports various instance types (general purpose, compute optimized, memory optimized, etc.)."},
		{ID: 3, Text: "What is S3?", Options: [4]string{"Simple Storage Service", "Object storage", "Scalable storage", "All of the above"}, CorrectAnswer: 3, Explanation: "S3 (Simple Storage Service) is AWS's object storage service. Stores data as objects in buckets. Highly scalable (unlimited storage), durable (99.999999999% durability), available. Supports versioning, encryption, lifecycle policies. Used for backups, static websites, data lakes, application data. Core AWS storage service."},
		{ID: 4, Text: "What is S3 storage class?", Options: [4]string{"Standard", "IA/Glacier", "Different tiers", "All of the above"}, CorrectAnswer: 3, Explanation: "S3 storage classes are different storage tiers optimized for different access patterns. Standard (frequent access), Standard-IA (infrequent access, lower cost), Glacier (archival, very low cost), Intelligent-Tiering (automatic optimization). Choose based on access frequency and cost requirements. Lifecycle policies can automatically transition objects."},
		{ID: 5, Text: "What is RDS?", Options: [4]string{"Relational Database Service", "Managed databases", "MySQL/PostgreSQL/etc", "All of the above"}, CorrectAnswer: 3, Explanation: "RDS (Relational Database Service) is AWS's managed relational database service. Supports MySQL, PostgreSQL, MariaDB, Oracle, SQL Server. Handles backups, patching, monitoring, scaling automatically. Multi-AZ for high availability, read replicas for scaling. Simplifies database administration. Focus on application, not database management."},
		{ID: 6, Text: "What is Lambda?", Options: [4]string{"Serverless compute", "Function as a Service", "Event-driven", "All of the above"}, CorrectAnswer: 3, Explanation: "Lambda is AWS's serverless compute service. Run code without provisioning servers. Pay only for compute time consumed. Event-driven - triggered by events (API calls, file uploads, schedule, etc.). Supports multiple languages. Auto-scales. Ideal for microservices, data processing, automation. No server management required."},
		{ID: 7, Text: "What is VPC?", Options: [4]string{"Virtual Private Cloud", "Isolated network", "Custom network", "All of the above"}, CorrectAnswer: 3, Explanation: "VPC (Virtual Private Cloud) provides an isolated virtual network in AWS. Define your own IP address range, subnets, route tables, gateways. Control network access with security groups and NACLs. Connect to on-premises via VPN or Direct Connect. Foundation for secure AWS networking. Default VPC provided, but custom VPCs recommended."},
		{ID: 8, Text: "What is IAM?", Options: [4]string{"Identity and Access Management", "User management", "Permissions", "All of the above"}, CorrectAnswer: 3, Explanation: "IAM (Identity and Access Management) controls access to AWS resources. Create users, groups, roles. Define permissions via policies (JSON documents). Principle of least privilege. MFA support. Access keys for programmatic access. Root account should be protected. Essential for AWS security. Centralized access control."},
		{ID: 9, Text: "What is CloudFormation?", Options: [4]string{"Infrastructure as Code", "Template-based", "Automated provisioning", "All of the above"}, CorrectAnswer: 3, Explanation: "CloudFormation enables Infrastructure as Code (IaC). Define infrastructure in YAML/JSON templates. Automatically provisions and manages AWS resources. Ensures consistency, repeatability. Version control infrastructure. Stack-based - create, update, delete entire stacks. Essential for DevOps and infrastructure automation. Reduces manual errors."},
		{ID: 10, Text: "What is CloudWatch?", Options: [4]string{"Monitoring", "Logging", "Metrics", "All of the above"}, CorrectAnswer: 3, Explanation: "CloudWatch is AWS's monitoring and observability service. Collects metrics from AWS services and applications. Stores and analyzes logs. Sets alarms and triggers actions. Dashboards for visualization. Integrated with most AWS services. Essential for monitoring AWS resources and applications. Helps maintain system health and performance."},
		{ID: 11, Text: "What is Route 53?", Options: [4]string{"DNS service", "Domain management", "Health checks", "All of the above"}, CorrectAnswer: 3, Explanation: "Route 53 is AWS's DNS (Domain Name System) service. Manages domain registration and DNS resolution. Routes traffic to AWS resources based on health checks. Supports various routing policies (simple, weighted, latency-based, geolocation, failover). Integrates with other AWS services. Essential for domain management and traffic routing."},
		{ID: 12, Text: "What is ELB?", Options: [4]string{"Elastic Load Balancer", "Distributes traffic", "High availability", "All of the above"}, CorrectAnswer: 3, Explanation: "ELB (Elastic Load Balancer) distributes incoming traffic across multiple targets (EC2 instances, containers, IPs). Types: Application Load Balancer (ALB), Network Load Balancer (NLB), Classic Load Balancer. Provides high availability, automatic scaling, health checks. Essential for distributing load and ensuring application availability."},
		{ID: 13, Text: "What is Auto Scaling?", Options: [4]string{"Automatic scaling", "Based on demand", "Maintains performance", "All of the above"}, CorrectAnswer: 3, Explanation: "Auto Scaling automatically adjusts capacity to maintain performance and minimize costs. Scales EC2 instances based on demand (CPU, memory, custom metrics). Maintains desired capacity. Can scale based on schedules or demand. Works with ELB for load distribution. Essential for handling variable workloads efficiently."},
		{ID: 14, Text: "What is EBS?", Options: [4]string{"Elastic Block Store", "Block storage", "EC2 volumes", "All of the above"}, CorrectAnswer: 3, Explanation: "EBS (Elastic Block Store) provides persistent block storage volumes for EC2 instances. Like virtual hard drives. Types: gp3/gp2 (general purpose), io1/io2 (provisioned IOPS), st1 (throughput optimized), sc1 (cold HDD). Can be attached/detached, backed up with snapshots. Essential for EC2 persistent storage."},
		{ID: 15, Text: "What is EFS?", Options: [4]string{"Elastic File System", "Managed NFS", "Shared storage", "All of the above"}, CorrectAnswer: 3, Explanation: "EFS (Elastic File System) provides managed NFS (Network File System) for EC2 instances. Shared file storage accessible by multiple instances simultaneously. Scales automatically. Pay for storage used. Supports EFS Standard and EFS Infrequent Access. Ideal for shared data, content management, web serving. Serverless - no provisioning needed."},
		{ID: 16, Text: "What is DynamoDB?", Options: [4]string{"NoSQL database", "Managed database", "Key-value store", "All of the above"}, CorrectAnswer: 3, Explanation: "DynamoDB is AWS's fully managed NoSQL database. Key-value and document database. Single-digit millisecond latency. Auto-scaling, built-in security, backups. Serverless - no servers to manage. Pay for what you use. Supports on-demand and provisioned capacity. Ideal for applications requiring consistent performance at scale."},
		{ID: 17, Text: "What is SQS?", Options: [4]string{"Simple Queue Service", "Message queue", "Decoupling", "All of the above"}, CorrectAnswer: 3, Explanation: "SQS (Simple Queue Service) is a fully managed message queuing service. Decouples and scales microservices, distributed systems, serverless applications. Two types: Standard (at-least-once delivery) and FIFO (exactly-once, ordered). Pull-based messaging. Essential for building scalable, resilient applications. Enables asynchronous processing."},
		{ID: 18, Text: "What is SNS?", Options: [4]string{"Simple Notification Service", "Pub/sub", "Notifications", "All of the above"}, CorrectAnswer: 3, Explanation: "SNS (Simple Notification Service) is a pub/sub messaging service. Sends notifications to multiple subscribers (email, SMS, SQS, Lambda, HTTP). Push-based messaging. Topics for grouping subscribers. Supports filtering. Essential for event-driven architectures and notifications. Decouples publishers and subscribers."},
		{ID: 19, Text: "What is CloudFront?", Options: [4]string{"CDN", "Content delivery", "Edge locations", "All of the above"}, CorrectAnswer: 3, Explanation: "CloudFront is AWS's Content Delivery Network (CDN). Caches content at edge locations worldwide for low latency. Delivers static and dynamic content. Integrates with S3, EC2, ELB, custom origins. Supports SSL/TLS, custom domains, signed URLs. Reduces load on origin servers. Essential for global content delivery and performance."},
		{ID: 20, Text: "What is API Gateway?", Options: [4]string{"API management", "REST/HTTP APIs", "Serverless APIs", "All of the above"}, CorrectAnswer: 3, Explanation: "API Gateway is a fully managed service for creating, publishing, and managing APIs. Supports REST and HTTP APIs. Integrates with Lambda, EC2, other AWS services. Handles authentication, throttling, caching, monitoring. Pay per API call. Essential for building serverless APIs and microservices. Provides API versioning and deployment stages."},
		{ID: 21, Text: "What is ECS?", Options: [4]string{"Elastic Container Service", "Container orchestration", "Docker support", "All of the above"}, CorrectAnswer: 3, Explanation: "ECS (Elastic Container Service) is AWS's container orchestration service. Runs Docker containers on EC2 or Fargate (serverless). Manages container lifecycle, scaling, load balancing. Two launch types: EC2 (manage infrastructure) and Fargate (serverless). Integrates with ALB, CloudWatch, IAM. Essential for containerized applications on AWS."},
		{ID: 22, Text: "What is EKS?", Options: [4]string{"Elastic Kubernetes Service", "Managed Kubernetes", "K8s on AWS", "All of the above"}, CorrectAnswer: 3, Explanation: "EKS (Elastic Kubernetes Service) is AWS's managed Kubernetes service. Runs Kubernetes clusters without managing control plane. Compatible with standard Kubernetes tools. Integrates with AWS services (IAM, VPC, ELB). Handles control plane availability and updates. Essential for Kubernetes workloads on AWS. Supports both EC2 and Fargate nodes."},
		{ID: 23, Text: "What is ECR?", Options: [4]string{"Elastic Container Registry", "Docker registry", "Image storage", "All of the above"}, CorrectAnswer: 3, Explanation: "ECR (Elastic Container Registry) is AWS's Docker container registry. Stores and manages Docker images. Integrated with ECS and EKS. Supports image scanning for vulnerabilities. Private registry with IAM access control. Pay for storage and data transfer. Essential for container image management on AWS."},
		{ID: 24, Text: "What is CodePipeline?", Options: [4]string{"CI/CD service", "Automated pipelines", "Deployment", "All of the above"}, CorrectAnswer: 3, Explanation: "CodePipeline is AWS's CI/CD service. Automates build, test, and deployment pipelines. Integrates with CodeBuild, CodeDeploy, GitHub, S3. Visual pipeline editor. Supports multiple stages and parallel actions. Pay per pipeline execution. Essential for DevOps automation. Enables continuous integration and deployment."},
		{ID: 25, Text: "What is CodeBuild?", Options: [4]string{"Build service", "Compiles code", "Runs tests", "All of the above"}, CorrectAnswer: 3, Explanation: "CodeBuild is AWS's fully managed build service. Compiles source code, runs tests, produces artifacts. Scales automatically - no servers to manage. Supports multiple languages and build environments. Pay for compute time used. Integrates with CodePipeline. Essential for CI/CD pipelines. Handles build dependencies automatically."},
		{ID: 26, Text: "What is CodeDeploy?", Options: [4]string{"Deployment service", "Automated deployments", "Rolling updates", "All of the above"}, CorrectAnswer: 3, Explanation: "CodeDeploy automates application deployments to EC2, Lambda, ECS, on-premises. Supports rolling, blue/green, and in-place deployments. Minimizes downtime. Automatic rollback on failure. Integrates with CodePipeline. Essential for reliable deployments. Handles deployment complexity automatically."},
		{ID: 27, Text: "What is Secrets Manager?", Options: [4]string{"Secret storage", "Rotation", "Encryption", "All of the above"}, CorrectAnswer: 3, Explanation: "Secrets Manager stores and manages secrets (passwords, API keys, tokens). Automatic rotation for RDS, Redshift, DocumentDB. Encrypted at rest and in transit. Integrates with IAM for access control. Pay per secret per month. Replaces hardcoded credentials. Essential for secure credential management. Better than Parameter Store for secrets requiring rotation."},
		{ID: 28, Text: "What is KMS?", Options: [4]string{"Key Management Service", "Encryption keys", "Key rotation", "All of the above"}, CorrectAnswer: 3, Explanation: "KMS (Key Management Service) creates and manages encryption keys. Customer Master Keys (CMKs) for encrypting data. Integrated with many AWS services (S3, EBS, RDS, etc.). Hardware Security Modules (HSM) for key storage. Supports key rotation. Essential for data encryption. Enables encryption at rest and in transit."},
		{ID: 29, Text: "What is WAF?", Options: [4]string{"Web Application Firewall", "Security", "DDoS protection", "All of the above"}, CorrectAnswer: 3, Explanation: "WAF (Web Application Firewall) protects web applications from common exploits. Filters HTTP/HTTPS traffic. Rules for SQL injection, XSS, rate limiting. Integrates with CloudFront, ALB, API Gateway. Custom rules or managed rule sets. Pay per rule per web ACL. Essential for web application security. Layer 7 protection."},
		{ID: 30, Text: "What is Shield?", Options: [4]string{"DDoS protection", "Managed protection", "Always-on", "All of the above"}, CorrectAnswer: 3, Explanation: "Shield provides DDoS (Distributed Denial of Service) protection. Shield Standard: free, always-on protection. Shield Advanced: enhanced protection with 24/7 support, cost protection, advanced mitigation. Protects EC2, ELB, CloudFront, Route 53, Global Accelerator. Automatic detection and mitigation. Essential for protecting against DDoS attacks."},
		{ID: 31, Text: "What is GuardDuty?", Options: [4]string{"Threat detection", "ML-based", "Security monitoring", "All of the above"}, CorrectAnswer: 3, Explanation: "GuardDuty is a threat detection service using machine learning. Analyzes VPC Flow Logs, CloudTrail, DNS logs. Detects compromised instances, malicious activity, unauthorized access. Pay per GB of data analyzed. Continuous monitoring. Sends findings to CloudWatch Events. Essential for security monitoring. No infrastructure to manage."},
		{ID: 32, Text: "What is Inspector?", Options: [4]string{"Security assessment", "Vulnerability scanning", "EC2/ECR scanning", "All of the above"}, CorrectAnswer: 3, Explanation: "Inspector performs automated security assessments. Scans EC2 instances and ECR images for vulnerabilities. Uses knowledge base of security best practices. Generates reports with findings and recommendations. Can be scheduled or triggered. Helps maintain security posture. Essential for vulnerability management. Identifies security issues automatically."},
		{ID: 33, Text: "What is Config?", Options: [4]string{"Configuration management", "Compliance", "Change tracking", "All of the above"}, CorrectAnswer: 3, Explanation: "Config tracks configuration changes to AWS resources. Records configuration history. Evaluates configurations against rules (compliance). Sends notifications on non-compliance. Provides configuration snapshots. Essential for compliance and auditing. Helps maintain desired configuration state. Integrates with CloudFormation and other services."},
		{ID: 34, Text: "What is Systems Manager?", Options: [4]string{"Operations management", "Patch management", "Parameter store", "All of the above"}, CorrectAnswer: 3, Explanation: "Systems Manager provides operations management capabilities. Patch Manager for patching EC2 instances. Parameter Store for configuration/secrets. Session Manager for secure shell access. Run Command for remote command execution. Automation for operational tasks. Essential for managing EC2 instances at scale. Unified operations management."},
		{ID: 35, Text: "What is CloudTrail?", Options: [4]string{"API logging", "Audit trail", "Compliance", "All of the above"}, CorrectAnswer: 3, Explanation: "CloudTrail logs all API calls made to AWS services. Provides audit trail of who did what, when, from where. Logs stored in S3. Can be analyzed with CloudWatch Logs Insights or Athena. Essential for security auditing and compliance. Tracks all management and data events. Enables governance and compliance."},
		{ID: 36, Text: "What is X-Ray?", Options: [4]string{"Distributed tracing", "Performance analysis", "Debugging", "All of the above"}, CorrectAnswer: 3, Explanation: "X-Ray provides distributed tracing for applications. Visualizes request flow through services. Identifies bottlenecks and errors. Service map shows dependencies. Trace analysis for debugging. Integrates with EC2, Lambda, ECS, ELB. Essential for debugging distributed applications. Helps understand application behavior and performance."},
		{ID: 37, Text: "What is Step Functions?", Options: [4]string{"Workflow orchestration", "State machines", "Serverless workflows", "All of the above"}, CorrectAnswer: 3, Explanation: "Step Functions orchestrates serverless workflows using state machines. Coordinates Lambda functions, ECS tasks, and other services. Visual workflow designer. Handles errors, retries, parallel execution. Pay per state transition. Essential for complex serverless workflows. Makes it easy to build and run multi-step applications."},
		{ID: 38, Text: "What is EventBridge?", Options: [4]string{"Event bus", "Event-driven architecture", "Serverless events", "All of the above"}, CorrectAnswer: 3, Explanation: "EventBridge is a serverless event bus. Routes events from AWS services, SaaS applications, custom applications. Event-driven architecture. Rules route events to targets (Lambda, SQS, SNS, etc.). Schema registry for event schemas. Replaces CloudWatch Events. Essential for event-driven applications. Decouples event producers and consumers."},
		{ID: 39, Text: "What is SES?", Options: [4]string{"Simple Email Service", "Email sending", "Transactional emails", "All of the above"}, CorrectAnswer: 3, Explanation: "SES (Simple Email Service) is AWS's email sending service. Send transactional emails, marketing emails, notifications. High deliverability. Pay for emails sent. Supports email templates, bounces, complaints handling. Can receive emails (with S3/SNS). Essential for application email functionality. Cost-effective email delivery."},
		{ID: 40, Text: "What is S3 Glacier?", Options: [4]string{"Archive storage", "Long-term storage", "Low cost", "All of the above"}, CorrectAnswer: 3, Explanation: "S3 Glacier is archival storage for long-term data retention. Very low cost storage. Retrieval times: Expedited (1-5 min), Standard (3-5 hours), Bulk (5-12 hours). Ideal for backups, archives, compliance data. Three tiers: Glacier Instant Retrieval, Glacier Flexible Retrieval, Glacier Deep Archive. Cheapest storage option."},
		{ID: 41, Text: "What is Redshift?", Options: [4]string{"Data warehouse", "Analytics", "OLAP", "All of the above"}, CorrectAnswer: 3, Explanation: "Redshift is AWS's fully managed data warehouse. Petabyte-scale analytics database. Columnar storage for fast queries. SQL-based. Integrates with BI tools. Supports data loading from S3, ETL tools. Auto-scaling and backups. Essential for business intelligence and analytics. Optimized for OLAP (Online Analytical Processing) workloads."},
		{ID: 42, Text: "What is Athena?", Options: [4]string{"Query S3", "Serverless analytics", "SQL queries", "All of the above"}, CorrectAnswer: 3, Explanation: "Athena is a serverless interactive query service. Query data in S3 using standard SQL. No infrastructure to manage. Pay per query per TB scanned. Works with various data formats (CSV, JSON, Parquet, etc.). Essential for ad-hoc analytics on S3 data. Fast and cost-effective for querying data lakes."},
		{ID: 43, Text: "What is EMR?", Options: [4]string{"Elastic MapReduce", "Big data processing", "Hadoop/Spark", "All of the above"}, CorrectAnswer: 3, Explanation: "EMR (Elastic MapReduce) is AWS's big data platform. Runs Hadoop, Spark, HBase, Presto, and other frameworks. Processes large datasets. Auto-scales clusters. Pay for compute time. Integrates with S3, DynamoDB, other AWS services. Essential for big data processing and analytics. Handles petabyte-scale data processing."},
		{ID: 44, Text: "What is Glue?", Options: [4]string{"ETL service", "Data catalog", "Serverless ETL", "All of the above"}, CorrectAnswer: 3, Explanation: "Glue is a serverless ETL (Extract, Transform, Load) service. Prepares and transforms data for analytics. Glue Data Catalog: metadata repository (like Hive metastore). Glue ETL: serverless Spark jobs. Auto-generates ETL code. Pay for compute time. Essential for data preparation and ETL pipelines. Integrates with many data sources."},
		{ID: 45, Text: "What is Kinesis?", Options: [4]string{"Streaming data", "Real-time processing", "Data streams", "All of the above"}, CorrectAnswer: 3, Explanation: "Kinesis is AWS's platform for streaming data. Kinesis Data Streams: real-time streaming data. Kinesis Data Firehose: load streams into S3, Redshift, etc. Kinesis Data Analytics: analyze streams with SQL. Handles millions of events per second. Essential for real-time data processing. Enables real-time analytics and processing."},
		{ID: 46, Text: "What is Cognito?", Options: [4]string{"User authentication", "Identity management", "Federated identities", "All of the above"}, CorrectAnswer: 3, Explanation: "Cognito provides user authentication and identity management. User Pools: user directory and authentication. Identity Pools: federated identities (access AWS resources). Supports social identity providers (Google, Facebook, etc.). MFA support. Essential for mobile and web applications. Handles user sign-up, sign-in, password management."},
		{ID: 47, Text: "What is Direct Connect?", Options: [4]string{"Dedicated connection", "Private network", "Bypass internet", "All of the above"}, CorrectAnswer: 3, Explanation: "Direct Connect establishes dedicated network connection from on-premises to AWS. Bypasses internet for more consistent performance. Lower latency, higher throughput. Private connectivity. Can reduce bandwidth costs. Supports 1Gbps and 10Gbps connections. Essential for hybrid cloud architectures. More reliable than VPN for production workloads."},
		{ID: 48, Text: "What is VPN?", Options: [4]string{"Site-to-site VPN", "Client VPN", "Secure connection", "All of the above"}, CorrectAnswer: 3, Explanation: "AWS VPN provides secure connections to VPCs. Site-to-Site VPN: connect on-premises network to VPC. Client VPN: connect individual devices to VPC. Encrypted over internet. Lower cost than Direct Connect but less reliable. Uses IPsec. Essential for secure remote access. Good for development, testing, or low-bandwidth production."},
		{ID: 49, Text: "What is Transit Gateway?", Options: [4]string{"Network hub", "VPC connectivity", "Centralized routing", "All of the above"}, CorrectAnswer: 3, Explanation: "Transit Gateway is a network transit hub. Connects VPCs, VPNs, Direct Connect in a central hub. Simplifies network architecture. Centralized routing. Reduces peering complexity. Supports route tables for segmentation. Pay per attachment and data processed. Essential for complex multi-VPC architectures. Hub-and-spoke model."},
		{ID: 50, Text: "What is CloudFormation stack?", Options: [4]string{"Collection of resources", "Template instance", "Managed unit", "All of the above"}, CorrectAnswer: 3, Explanation: "A CloudFormation stack is a collection of AWS resources created from a template. Single unit of management - create, update, delete together. Tracks dependencies between resources. Rollback on failure. Stack events show progress. Can have nested stacks. Essential for infrastructure management. Represents a complete application or environment."},
		{ID: 51, Text: "What is a region?", Options: [4]string{"Geographic area", "Data center location", "Isolated area", "All of the above"}, CorrectAnswer: 3, Explanation: "A region is a geographic area containing multiple Availability Zones. Each region is isolated and independent. Choose regions based on latency, compliance, data residency. Resources are region-specific (not global). Examples: us-east-1, eu-west-1, ap-southeast-1. Essential for global deployments and compliance."},
		{ID: 52, Text: "What is an availability zone?", Options: [4]string{"Data center", "Isolated location", "High availability", "All of the above"}, CorrectAnswer: 3, Explanation: "An Availability Zone (AZ) is one or more discrete data centers in a region. Isolated from failures in other AZs. Connected via low-latency links. Deploy across multiple AZs for high availability. Each region has 2-6 AZs. Essential for fault tolerance and disaster recovery."},
		{ID: 53, Text: "What is multi-AZ?", Options: [4]string{"Multiple AZs", "High availability", "Disaster recovery", "All of the above"}, CorrectAnswer: 3, Explanation: "Multi-AZ deployment runs resources across multiple Availability Zones. Provides high availability - if one AZ fails, resources in other AZs continue. Automatic failover for RDS, ElastiCache. Reduces downtime risk. Essential for production workloads. Increases availability from ~99.5% to 99.95%+."},
		{ID: 54, Text: "What is a security group?", Options: [4]string{"Virtual firewall", "EC2 rules", "Inbound/outbound", "All of the above"}, CorrectAnswer: 3, Explanation: "A security group is a virtual firewall for EC2 instances. Controls inbound and outbound traffic. Stateful - return traffic automatically allowed. Default: deny all inbound, allow all outbound. Can reference other security groups. Essential for network security. Applied at instance level."},
		{ID: 55, Text: "What is a NACL?", Options: [4]string{"Network ACL", "Subnet firewall", "Stateless", "All of the above"}, CorrectAnswer: 3, Explanation: "NACL (Network Access Control List) is a subnet-level firewall. Stateless - must allow both directions explicitly. Rules evaluated in order (lowest number first). Default NACL allows all traffic. More granular than security groups. Essential for subnet-level network control. Applied at subnet level."},
		{ID: 56, Text: "What is an IAM role?", Options: [4]string{"Permissions", "Assumed by services", "Temporary credentials", "All of the above"}, CorrectAnswer: 3, Explanation: "An IAM role is a set of permissions that can be assumed by AWS services or users. Provides temporary credentials (STS). No long-term credentials. EC2 instances, Lambda, other services assume roles. More secure than access keys. Essential for service-to-service access. Enables least privilege access."},
		{ID: 57, Text: "What is an IAM policy?", Options: [4]string{"Permission document", "JSON policy", "Allow/deny", "All of the above"}, CorrectAnswer: 3, Explanation: "An IAM policy is a JSON document defining permissions. Specifies what actions are allowed/denied on which resources. Attached to users, groups, or roles. Can be managed (AWS-provided) or custom. Effect: Allow or Deny. Essential for access control. Principle of least privilege should be applied."},
		{ID: 58, Text: "What is least privilege?", Options: [4]string{"Minimum permissions", "Security principle", "Only needed access", "All of the above"}, CorrectAnswer: 3, Explanation: "Least privilege is a security principle granting minimum permissions needed. Users/services get only what they need, nothing more. Reduces attack surface. Essential security best practice. Review and remove unused permissions regularly. Prevents privilege escalation and reduces risk."},
		{ID: 59, Text: "What is MFA?", Options: [4]string{"Multi-factor authentication", "Two-factor", "Additional security", "All of the above"}, CorrectAnswer: 3, Explanation: "MFA (Multi-Factor Authentication) requires additional authentication beyond password. Something you know (password) + something you have (device). Virtual MFA devices (apps) or hardware MFA devices. Required for root account, recommended for IAM users. Essential for account security. Prevents unauthorized access even if password is compromised."},
		{ID: 60, Text: "What is encryption at rest?", Options: [4]string{"Encrypted storage", "Data encryption", "KMS encryption", "All of the above"}, CorrectAnswer: 3, Explanation: "Encryption at rest encrypts data stored on disk. Protects data when not in use. S3, EBS, RDS support encryption. Uses KMS keys or service-managed keys. Required for compliance (HIPAA, PCI-DSS). Essential for data security. Prevents unauthorized access to stored data."},
		{ID: 61, Text: "What is encryption in transit?", Options: [4]string{"TLS/SSL", "Encrypted transmission", "Secure communication", "All of the above"}, CorrectAnswer: 3, Explanation: "Encryption in transit encrypts data during transmission. Uses TLS/SSL protocols. Protects data between client and server, between services. Required for compliance. HTTPS for web traffic, encrypted connections for databases. Essential for data security. Prevents interception and man-in-the-middle attacks."},
		{ID: 62, Text: "What is a snapshot?", Options: [4]string{"EBS backup", "Point-in-time copy", "Incremental", "All of the above"}, CorrectAnswer: 3, Explanation: "A snapshot is a point-in-time backup of an EBS volume. Stored in S3. Incremental - only changed blocks saved. Can create volumes from snapshots. Used for backups, disaster recovery, volume migration. Can be automated with lifecycle policies. Essential for data protection."},
		{ID: 63, Text: "What is AMI?", Options: [4]string{"Amazon Machine Image", "EC2 template", "OS + software", "All of the above"}, CorrectAnswer: 3, Explanation: "AMI (Amazon Machine Image) is a template for EC2 instances. Contains OS, application server, applications. Launch instances from AMIs. Can create custom AMIs from running instances. Shared AMIs available or create your own. Essential for consistent deployments. Enables golden images and fast scaling."},
		{ID: 64, Text: "What is instance type?", Options: [4]string{"EC2 size", "CPU/memory", "Performance", "All of the above"}, CorrectAnswer: 3, Explanation: "Instance type determines EC2 instance size and capabilities. Defines vCPU, memory, network performance, storage. Families: general purpose (t3, m5), compute optimized (c5), memory optimized (r5), storage optimized (i3). Choose based on workload requirements. Right-sizing saves costs. Essential for performance optimization."},
		{ID: 65, Text: "What is spot instance?", Options: [4]string{"Discount pricing", "Interruptible", "Cost savings", "All of the above"}, CorrectAnswer: 3, Explanation: "Spot instances use spare EC2 capacity at up to 90% discount. Can be interrupted with 2-minute notice when capacity needed. Ideal for fault-tolerant, flexible workloads. Set maximum price. Cost-effective for batch processing, data analysis, CI/CD. Not suitable for persistent workloads. Essential for cost optimization."},
		{ID: 66, Text: "What is reserved instance?", Options: [4]string{"Commitment discount", "1-3 year term", "Cost savings", "All of the above"}, CorrectAnswer: 3, Explanation: "Reserved Instances provide discount (up to 75%) for 1-3 year commitment. Predictable workloads benefit most. Payment options: All Upfront, Partial Upfront, No Upfront. Can be Standard (modifiable) or Convertible (exchangeable). Regional or Zonal. Essential for cost optimization of steady-state workloads."},
		{ID: 67, Text: "What is on-demand instance?", Options: [4]string{"Pay as you go", "No commitment", "Flexible", "All of the above"}, CorrectAnswer: 3, Explanation: "On-demand instances are pay-as-you-go with no upfront costs or commitments. Most flexible pricing. Pay for compute capacity by the hour/second. No long-term commitments. Good for unpredictable workloads, testing, short-term projects. Most expensive but most flexible. Default pricing model."},
		{ID: 68, Text: "What is a bucket?", Options: [4]string{"S3 container", "Object storage", "Global namespace", "All of the above"}, CorrectAnswer: 3, Explanation: "A bucket is an S3 container for objects. Globally unique name across all AWS accounts. Region-specific. Can store unlimited objects. Configure versioning, lifecycle, encryption, access policies per bucket. Essential S3 concept. Organizes objects. Root of S3 storage hierarchy."},
		{ID: 69, Text: "What is versioning?", Options: [4]string{"Object versions", "S3 feature", "Recovery", "All of the above"}, CorrectAnswer: 3, Explanation: "S3 versioning keeps multiple versions of objects. Protects against accidental deletion/overwrite. Can restore previous versions. Each version has unique version ID. Can enable MFA Delete for extra protection. Increases storage costs. Essential for data protection and compliance. Enables point-in-time recovery."},
		{ID: 70, Text: "What is lifecycle policy?", Options: [4]string{"Automated transitions", "S3 rules", "Cost optimization", "All of the above"}, CorrectAnswer: 3, Explanation: "Lifecycle policies automatically transition objects between storage classes or delete them. Move to cheaper storage (Standard → IA → Glacier). Delete old objects. Based on age or date. Reduces storage costs automatically. Essential for cost optimization. Set at bucket level. Can have multiple rules."},
		{ID: 71, Text: "What is replication?", Options: [4]string{"Cross-region copy", "Disaster recovery", "Compliance", "All of the above"}, CorrectAnswer: 3, Explanation: "S3 replication copies objects to another bucket (cross-region or same-region). Asynchronous replication. Use cases: disaster recovery, compliance, latency reduction, backup. Can replicate to different storage classes. Versioning must be enabled on source. Essential for data redundancy and compliance."},
		{ID: 72, Text: "What is a VPC endpoint?", Options: [4]string{"Private connection", "No internet", "AWS services", "All of the above"}, CorrectAnswer: 3, Explanation: "VPC endpoints provide private connectivity to AWS services. No internet gateway, NAT, or VPN needed. Two types: Gateway endpoints (S3, DynamoDB) and Interface endpoints (other services). Reduces data transfer costs. Improves security. Essential for private access to AWS services. Keeps traffic within AWS network."},
		{ID: 73, Text: "What is NAT Gateway?", Options: [4]string{"Outbound internet", "Private subnet access", "Managed NAT", "All of the above"}, CorrectAnswer: 3, Explanation: "NAT Gateway allows instances in private subnets to access internet outbound. Managed service (no EC2 instance to manage). Highly available (deploy in multiple AZs). Provides static IP addresses. Required for private subnet internet access (updates, downloads). Essential for private subnet connectivity. More reliable than NAT instance."},
		{ID: 74, Text: "What is Internet Gateway?", Options: [4]string{"VPC internet access", "Public subnet", "One per VPC", "All of the above"}, CorrectAnswer: 3, Explanation: "Internet Gateway enables VPC to connect to internet. One per VPC. Provides public IP addresses. Required for public subnets. Two-way communication (inbound and outbound). Attached to VPC, added to route tables. Essential for public internet access. Enables public-facing resources."},
		{ID: 75, Text: "What is a subnet?", Options: [4]string{"Network segment", "IP range", "VPC subdivision", "All of the above"}, CorrectAnswer: 3, Explanation: "A subnet is a range of IP addresses in a VPC. Subdivides VPC into smaller networks. Each subnet is in one AZ. Can be public (internet gateway route) or private (NAT gateway). Route table controls traffic. Essential VPC component. Enables network segmentation and security."},
		{ID: 76, Text: "What is public subnet?", Options: [4]string{"Internet gateway route", "Public IPs", "Internet access", "All of the above"}, CorrectAnswer: 3, Explanation: "A public subnet has a route to an internet gateway. Instances can have public IPs. Accessible from internet (if security groups allow). Used for load balancers, NAT gateways, bastion hosts. Route table includes 0.0.0.0/0 → Internet Gateway. Essential for public-facing resources."},
		{ID: 77, Text: "What is private subnet?", Options: [4]string{"No internet gateway", "NAT gateway", "Isolated", "All of the above"}, CorrectAnswer: 3, Explanation: "A private subnet has no direct route to internet gateway. Instances typically have private IPs only. Can use NAT Gateway for outbound internet. More secure - not directly accessible from internet. Used for databases, application servers. Route table has no internet gateway route. Essential for backend resources."},
		{ID: 78, Text: "What is Route Table?", Options: [4]string{"Routing rules", "Subnet routing", "Traffic direction", "All of the above"}, CorrectAnswer: 3, Explanation: "Route tables contain rules (routes) that determine where network traffic is directed. Each subnet must be associated with a route table. Routes specify destination (CIDR) and target (gateway, instance, etc.). Default route table created with VPC. Custom route tables for different subnets. Essential for network routing."},
		{ID: 79, Text: "What is CloudFormation template?", Options: [4]string{"YAML/JSON", "Resource definition", "Infrastructure code", "All of the above"}, CorrectAnswer: 3, Explanation: "A CloudFormation template is a YAML or JSON file defining AWS resources. Declarative - describes desired state. Contains Resources, Parameters, Outputs, Mappings, Conditions. Version controlled. Reusable and shareable. Essential for Infrastructure as Code. Single source of truth for infrastructure."},
		{ID: 80, Text: "What is a parameter?", Options: [4]string{"Template input", "Customizable values", "Reusable", "All of the above"}, CorrectAnswer: 3, Explanation: "Parameters are inputs to CloudFormation templates. Make templates reusable with different values. Types: String, Number, List, CommaDelimitedList. Can have defaults, allowed values, descriptions. Provided at stack creation/update. Essential for template flexibility. Enables one template for multiple environments."},
		{ID: 81, Text: "What is an output?", Options: [4]string{"Stack output", "Exported values", "Stack information", "All of the above"}, CorrectAnswer: 3, Explanation: "Outputs export values from a CloudFormation stack. Can reference outputs from other stacks. Useful for sharing information (IPs, ARNs, etc.). Displayed after stack creation. Can be exported for cross-stack references. Essential for stack integration. Provides stack information to users/other stacks."},
		{ID: 82, Text: "What is a resource?", Options: [4]string{"AWS component", "Template element", "Provisioned item", "All of the above"}, CorrectAnswer: 3, Explanation: "Resources are AWS components defined in CloudFormation templates. Each resource has a Type (e.g., AWS::EC2::Instance) and Properties. CloudFormation provisions actual AWS resources from template. Core template element. Can reference other resources. Essential for infrastructure definition. Represents actual AWS resources."},
		{ID: 83, Text: "What is drift detection?", Options: [4]string{"Configuration changes", "Template vs actual", "Compliance check", "All of the above"}, CorrectAnswer: 3, Explanation: "Drift detection identifies differences between template and actual resource configuration. Detects manual changes outside CloudFormation. Helps maintain infrastructure consistency. Can detect configuration drift. Essential for compliance and change management. Ensures infrastructure matches template definition."},
		{ID: 84, Text: "What is change set?", Options: [4]string{"Preview changes", "Before apply", "Review modifications", "All of the above"}, CorrectAnswer: 3, Explanation: "A change set previews modifications before applying stack update. Shows what will change, be created, deleted, replaced. Review before executing. Can create multiple change sets. Execute the one you want. Essential for safe updates. Prevents unexpected changes."},
		{ID: 85, Text: "What is stack update?", Options: [4]string{"Modify stack", "Change resources", "Update template", "All of the above"}, CorrectAnswer: 3, Explanation: "Stack update modifies an existing stack with a new template. Can add, modify, or delete resources. CloudFormation determines changes needed. Some changes require replacement (new resource). Use change sets to preview. Essential for infrastructure evolution. Maintains stack state and relationships."},
		{ID: 86, Text: "What is stack deletion?", Options: [4]string{"Remove stack", "Delete resources", "Cleanup", "All of the above"}, CorrectAnswer: 3, Explanation: "Stack deletion removes a CloudFormation stack and its resources. Deletes resources in reverse dependency order. Can retain resources with DeletionPolicy. Useful for cleanup and cost management. Removes all stack-managed resources. Essential for infrastructure lifecycle management. Use carefully - can delete production resources."},
		{ID: 87, Text: "What is nested stack?", Options: [4]string{"Stack in stack", "Modular templates", "Reusability", "All of the above"}, CorrectAnswer: 3, Explanation: "Nested stacks are stacks created within another stack. Enables modular templates. Reuse common components. Simplify complex templates. Parent stack manages nested stacks. Essential for template organization. Promotes reusability and maintainability."},
		{ID: 88, Text: "What is cross-stack reference?", Options: [4]string{"Stack outputs", "Share values", "Dependencies", "All of the above"}, CorrectAnswer: 3, Explanation: "Cross-stack references allow stacks to share values. Export outputs from one stack, import in another. Enables stack dependencies. Loose coupling between stacks. Essential for modular architectures. Allows independent stack management while sharing data."},
		{ID: 89, Text: "What is SAM?", Options: [4]string{"Serverless Application Model", "Lambda templates", "Simplified CF", "All of the above"}, CorrectAnswer: 3, Explanation: "SAM (Serverless Application Model) is an extension of CloudFormation for serverless applications. Simplified syntax for Lambda, API Gateway, DynamoDB. Transforms SAM templates to CloudFormation. Easier than raw CloudFormation for serverless. Essential for serverless development. Reduces boilerplate for Lambda functions."},
		{ID: 90, Text: "What is CDK?", Options: [4]string{"Cloud Development Kit", "Code-based IaC", "Programming languages", "All of the above"}, CorrectAnswer: 3, Explanation: "CDK (Cloud Development Kit) defines infrastructure using programming languages (TypeScript, Python, Java, C#, Go). Generates CloudFormation templates. Object-oriented approach. Reusable constructs. Type-safe infrastructure. Essential for developers preferring code over YAML/JSON. Combines power of CloudFormation with programming languages."},
		{ID: 91, Text: "What is Well-Architected Framework?", Options: [4]string{"Best practices", "5 pillars", "Architecture guidance", "All of the above"}, CorrectAnswer: 3, Explanation: "Well-Architected Framework provides architectural best practices. Five pillars: Security, Reliability, Performance Efficiency, Cost Optimization, Operational Excellence. Helps design and operate secure, high-performing systems. Review architecture against framework. Essential for building production-ready systems. AWS best practices guide."},
		{ID: 92, Text: "What are the 5 pillars?", Options: [4]string{"Security/Reliability/Performance/Cost/Ops", "5 principles", "Architecture areas", "All of the above"}, CorrectAnswer: 3, Explanation: "The 5 pillars are: Security (protect systems/data), Reliability (recover from failures), Performance Efficiency (use resources efficiently), Cost Optimization (avoid unnecessary costs), Operational Excellence (run/monitor systems). Foundation of Well-Architected Framework. Essential for building robust architectures. Balance all pillars."},
		{ID: 93, Text: "What is cost optimization?", Options: [4]string{"Reduce costs", "Right-sizing", "Reserved instances", "All of the above"}, CorrectAnswer: 3, Explanation: "Cost optimization pillar focuses on avoiding unnecessary costs. Right-size resources, use Reserved Instances, eliminate unused resources, optimize data transfer. Monitor costs with Cost Explorer. Use Trusted Advisor recommendations. Essential for efficient cloud spending. Maximize value while minimizing costs."},
		{ID: 94, Text: "What is operational excellence?", Options: [4]string{"Operations best practices", "Automation", "Monitoring", "All of the above"}, CorrectAnswer: 3, Explanation: "Operational Excellence pillar focuses on running and monitoring systems. Automate changes, respond to events, define standards. Use CloudFormation, CodePipeline, CloudWatch. Document procedures. Essential for efficient operations. Enables continuous improvement and learning from failures."},
		{ID: 95, Text: "What is performance efficiency?", Options: [4]string{"Right-sizing", "Performance optimization", "Scaling", "All of the above"}, CorrectAnswer: 3, Explanation: "Performance Efficiency pillar focuses on using computing resources efficiently. Right-size resources, use advanced technologies, monitor performance, trade-offs. Auto Scaling, caching, CDN. Essential for optimal performance. Maximize performance while minimizing cost. Adapt to changing requirements."},
		{ID: 96, Text: "What is reliability?", Options: [4]string{"High availability", "Fault tolerance", "Disaster recovery", "All of the above"}, CorrectAnswer: 3, Explanation: "Reliability pillar focuses on system recovery from failures. Design for failure, test recovery procedures, scale horizontally, automate recovery. Multi-AZ, Auto Scaling, health checks. Essential for production systems. Ensures system can recover from infrastructure/service failures automatically."},
		{ID: 97, Text: "What is security?", Options: [4]string{"Protection", "Encryption", "Access control", "All of the above"}, CorrectAnswer: 3, Explanation: "Security pillar focuses on protecting systems and data. Implement strong identity foundation (IAM), enable traceability (CloudTrail), apply security at all layers, automate security best practices, protect data in transit and at rest. Essential for secure architectures. Defense in depth approach."},
		{ID: 98, Text: "What is Trusted Advisor?", Options: [4]string{"Best practices", "Cost optimization", "Security checks", "All of the above"}, CorrectAnswer: 3, Explanation: "Trusted Advisor analyzes AWS account and provides recommendations. Checks: cost optimization, security, fault tolerance, performance, service limits. Free tier: core checks. Business/Enterprise: all checks. Essential for optimization. Helps identify opportunities to save money and improve security/reliability."},
		{ID: 99, Text: "What is Cost Explorer?", Options: [4]string{"Cost analysis", "Spending trends", "Forecasting", "All of the above"}, CorrectAnswer: 3, Explanation: "Cost Explorer visualizes and analyzes AWS costs. View spending by service, account, tag, etc. Historical data and forecasts. Identify cost drivers. Create custom reports. Essential for cost management. Helps understand where money is spent. Enables data-driven cost optimization decisions."},
		{ID: 100, Text: "What is AWS Organizations?", Options: [4]string{"Account management", "Consolidated billing", "Policy management", "All of the above"}, CorrectAnswer: 3, Explanation: "AWS Organizations manages multiple AWS accounts. Consolidated billing - single bill for all accounts. Organizational units (OUs) for grouping. Service Control Policies (SCPs) for account governance. Centralized management. Essential for enterprises. Simplifies account management and cost allocation. Enables policy-based account management."},
		{ID: 101, Text: "What is a Service Control Policy (SCP)?", Options: [4]string{"Account-level policy", "Organization-wide guardrails", "Permission boundaries", "All of the above"}, CorrectAnswer: 3, Explanation: "SCPs are organization-wide policies that control what services and actions can be used in member accounts. Act as guardrails - cannot grant permissions, only deny. Applied at OU or account level. Cannot restrict root user. Essential for centralized governance. Helps enforce compliance and security policies across organization."},
		{ID: 102, Text: "What is AWS Control Tower?", Options: [4]string{"Multi-account management", "Landing zone", "Governance automation", "All of the above"}, CorrectAnswer: 3, Explanation: "Control Tower automates setup of secure, compliant multi-account AWS environment. Creates landing zone with best practices. Manages accounts, guardrails, compliance. Built on Organizations, Config, CloudTrail. Essential for enterprises starting AWS journey. Provides prescriptive guidance and automated setup. Simplifies multi-account governance."},
		{ID: 103, Text: "What is AWS Backup?", Options: [4]string{"Centralized backup", "Cross-service backup", "Automated backups", "All of the above"}, CorrectAnswer: 3, Explanation: "AWS Backup provides centralized backup service across AWS services. Supports EC2, EBS, RDS, DynamoDB, EFS, Storage Gateway, and more. Policy-based backup scheduling. Cross-region backup. Lifecycle management. Essential for unified backup strategy. Simplifies backup management across multiple services."},
		{ID: 104, Text: "What is AWS DataSync?", Options: [4]string{"Data transfer", "On-premises to AWS", "Fast migration", "All of the above"}, CorrectAnswer: 3, Explanation: "DataSync transfers data between on-premises and AWS storage services. Faster than open-source tools. Uses parallel streams and compression. Incremental transfers. Supports S3, EFS, FSx. Essential for data migration and hybrid cloud. Reduces transfer time and costs compared to standard tools."},
		{ID: 105, Text: "What is AWS Storage Gateway?", Options: [4]string{"Hybrid storage", "On-premises cache", "S3/NFS/iSCSI", "All of the above"}, CorrectAnswer: 3, Explanation: "Storage Gateway connects on-premises environments to AWS storage. Three types: File Gateway (S3 via NFS/SMB), Volume Gateway (EBS via iSCSI), Tape Gateway (S3 Glacier via VTL). Caches frequently accessed data locally. Essential for hybrid cloud storage. Enables seamless integration between on-premises and cloud."},
		{ID: 106, Text: "What is AWS AppSync?", Options: [4]string{"GraphQL API", "Real-time subscriptions", "Managed GraphQL", "All of the above"}, CorrectAnswer: 3, Explanation: "AppSync is a managed GraphQL service. Builds scalable APIs with real-time subscriptions. Integrates with DynamoDB, Lambda, Elasticsearch, HTTP APIs. Handles offline support, conflict resolution. Pay per query. Essential for mobile and web applications. Simplifies building GraphQL APIs with real-time capabilities."},
		{ID: 107, Text: "What is AWS Amplify?", Options: [4]string{"Full-stack platform", "Mobile/web apps", "CI/CD for frontend", "All of the above"}, CorrectAnswer: 3, Explanation: "Amplify is a full-stack platform for building mobile and web applications. Provides authentication, storage, API, hosting, CI/CD. Integrates with Cognito, AppSync, S3, CloudFront. Simplifies frontend development. Essential for rapid application development. Handles backend infrastructure automatically."},
		{ID: 108, Text: "What is AWS App Mesh?", Options: [4]string{"Service mesh", "Microservices networking", "Observability", "All of the above"}, CorrectAnswer: 3, Explanation: "App Mesh is a service mesh for microservices. Manages service-to-service communication. Provides traffic management, observability, security. Works with ECS, EKS, EC2, Fargate. Envoy proxy-based. Essential for complex microservices architectures. Simplifies service communication and provides consistent networking."},
		{ID: 109, Text: "What is AWS Global Accelerator?", Options: [4]string{"Performance improvement", "Static IPs", "Traffic routing", "All of the above"}, CorrectAnswer: 3, Explanation: "Global Accelerator improves availability and performance of applications. Uses AWS edge locations to route traffic. Provides static IP addresses. Automatic failover. Routes to nearest healthy endpoint. Essential for global applications. Reduces latency and improves availability compared to single-region deployments."},
		{ID: 110, Text: "What is AWS Outposts?", Options: [4]string{"On-premises AWS", "Hybrid cloud", "AWS hardware on-site", "All of the above"}, CorrectAnswer: 3, Explanation: "Outposts brings AWS infrastructure to on-premises data centers. Same APIs, services, tools as AWS cloud. For low-latency requirements, data residency, local data processing. Fully managed by AWS. Essential for hybrid cloud with strict latency or data residency requirements. Seamless extension of AWS cloud."},
		{ID: 111, Text: "What is AWS Wavelength?", Options: [4]string{"5G edge computing", "Ultra-low latency", "Mobile edge", "All of the above"}, CorrectAnswer: 3, Explanation: "Wavelength embeds AWS compute and storage in 5G networks. Ultra-low latency for mobile applications. Deploy at carrier edge locations. Essential for real-time mobile applications (gaming, AR/VR, ML inference). Reduces latency to single-digit milliseconds. Extends AWS to edge of 5G networks."},
		{ID: 112, Text: "What is AWS Local Zones?", Options: [4]string{"Metro edge", "Low latency", "Single-digit ms", "All of the above"}, CorrectAnswer: 3, Explanation: "Local Zones are AWS infrastructure in metropolitan areas. Brings AWS services closer to end users. Single-digit millisecond latency. Supports EC2, EBS, VPC, ECS, EKS. Essential for latency-sensitive applications. Extends AWS regions to major cities. Reduces latency for local users."},
		{ID: 113, Text: "What is AWS Fargate?", Options: [4]string{"Serverless containers", "No EC2 management", "ECS/EKS option", "All of the above"}, CorrectAnswer: 3, Explanation: "Fargate is serverless compute for containers. Run containers without managing servers. Works with ECS and EKS. Pay for vCPU and memory used. No EC2 instances to manage. Essential for container workloads without infrastructure management. Simplifies container deployment and scaling."},
		{ID: 114, Text: "What is AWS Batch?", Options: [4]string{"Batch computing", "Job scheduling", "HPC workloads", "All of the above"}, CorrectAnswer: 3, Explanation: "Batch runs large-scale batch computing workloads. Dynamically provisions compute resources. Handles job scheduling, queuing, execution. Supports EC2 and Spot Instances. Essential for HPC, data processing, ML training. Pay only for resources used. Automatically scales based on workload."},
		{ID: 115, Text: "What is AWS Elastic Beanstalk?", Options: [4]string{"Platform as a Service", "Application deployment", "Managed platform", "All of the above"}, CorrectAnswer: 3, Explanation: "Elastic Beanstalk is a PaaS for deploying applications. Supports multiple languages (Java, .NET, PHP, Node.js, Python, Ruby, Go, Docker). Handles capacity provisioning, load balancing, auto-scaling, monitoring. Developer focuses on code. Essential for rapid deployment. Simplifies application deployment and management."},
		{ID: 116, Text: "What is AWS Lightsail?", Options: [4]string{"Simplified VPS", "Fixed pricing", "Easy setup", "All of the above"}, CorrectAnswer: 3, Explanation: "Lightsail provides virtual private servers with fixed pricing. Simplified EC2 alternative. Includes compute, storage, networking. Pre-configured application stacks. Predictable monthly pricing. Essential for simple applications, websites, development. Easier than EC2 for basic use cases. Good for getting started with AWS."},
		{ID: 117, Text: "What is AWS App Runner?", Options: [4]string{"Container deployment", "Source to URL", "Managed containers", "All of the above"}, CorrectAnswer: 3, Explanation: "App Runner builds and runs containerized applications from source code or container image. Automatic scaling, load balancing, encryption. Pay for compute used. Essential for web applications and APIs. Simplifies container deployment. No infrastructure management required."},
		{ID: 118, Text: "What is AWS Proton?", Options: [4]string{"Container platform", "Self-service infrastructure", "Template-based", "All of the above"}, CorrectAnswer: 3, Explanation: "Proton provides self-service container and serverless application deployment. Platform teams define templates, developers deploy. Standardizes infrastructure. Integrates with CodePipeline, CodeBuild. Essential for platform engineering. Enables self-service while maintaining standards. Reduces operational overhead."},
		{ID: 119, Text: "What is AWS CodeCommit?", Options: [4]string{"Git repository", "Source control", "Private repos", "All of the above"}, CorrectAnswer: 3, Explanation: "CodeCommit is a managed Git repository service. Private, scalable, secure. Integrates with CodePipeline, CodeBuild. No size limits. Pay for storage and requests. Essential for AWS-native CI/CD. Fully managed alternative to GitHub/GitLab. Encrypted at rest and in transit."},
		{ID: 120, Text: "What is AWS CodeArtifact?", Options: [4]string{"Package repository", "Maven/npm/pip", "Dependency management", "All of the above"}, CorrectAnswer: 3, Explanation: "CodeArtifact is a managed artifact repository. Supports Maven, npm, pip, NuGet, and more. Private package storage. Integrates with CodeBuild, CodePipeline. Pay for storage and requests. Essential for secure dependency management. Reduces external dependency on public repositories."},
		{ID: 121, Text: "What is AWS CodeStar?", Options: [4]string{"Project management", "CI/CD templates", "Quick start", "All of the above"}, CorrectAnswer: 3, Explanation: "CodeStar provides unified project management for software development. Pre-configured project templates. Sets up CI/CD pipelines automatically. Dashboard for project activity. Integrates CodeCommit, CodeBuild, CodeDeploy, CodePipeline. Essential for quick project setup. Simplifies getting started with AWS development tools."},
		{ID: 122, Text: "What is AWS Device Farm?", Options: [4]string{"Mobile testing", "Real devices", "App testing", "All of the above"}, CorrectAnswer: 3, Explanation: "Device Farm tests mobile apps on real devices in the cloud. Supports iOS, Android, web apps. Automated testing or manual testing. Access to hundreds of device configurations. Essential for mobile app quality assurance. Reduces need for physical device labs. Pay per device minute used."},
		{ID: 123, Text: "What is AWS Cloud9?", Options: [4]string{"Cloud IDE", "Browser-based", "Collaborative coding", "All of the above"}, CorrectAnswer: 3, Explanation: "Cloud9 is a cloud-based integrated development environment. Browser-based, no installation needed. Pre-configured with AWS SDKs. Collaborative coding. Connects to EC2 or own servers. Essential for cloud-native development. Simplifies development environment setup. Integrated with AWS services."},
		{ID: 124, Text: "What is AWS Systems Manager Session Manager?", Options: [4]string{"Secure shell", "No SSH keys", "Browser-based access", "All of the above"}, CorrectAnswer: 3, Explanation: "Session Manager provides secure shell access to EC2 instances. No SSH keys or bastion hosts needed. Browser-based or CLI. Encrypted sessions. Audit logs in CloudTrail. Essential for secure instance access. Eliminates need for SSH key management. Integrated with IAM for access control."},
		{ID: 125, Text: "What is AWS Systems Manager Parameter Store?", Options: [4]string{"Configuration storage", "Secrets management", "Hierarchical storage", "All of the above"}, CorrectAnswer: 3, Explanation: "Parameter Store stores configuration data and secrets. Hierarchical organization. Supports plaintext and encrypted (KMS) values. Versioning and history. Free for standard parameters. Essential for application configuration. Better than hardcoding values. Integrates with Lambda, ECS, EC2."},
		{ID: 126, Text: "What is AWS Systems Manager Patch Manager?", Options: [4]string{"Automated patching", "EC2 patching", "Compliance", "All of the above"}, CorrectAnswer: 3, Explanation: "Patch Manager automates patching of EC2 instances and on-premises servers. Schedules patching, maintains patch compliance. Supports Windows and Linux. Can use maintenance windows. Essential for security compliance. Reduces manual patching effort. Helps maintain system security."},
		{ID: 127, Text: "What is AWS Systems Manager Run Command?", Options: [4]string{"Remote execution", "Bulk commands", "EC2 management", "All of the above"}, CorrectAnswer: 3, Explanation: "Run Command executes commands on EC2 instances remotely. No SSH needed. Can target multiple instances. Secure, auditable. Integrates with IAM. Essential for bulk operations. Useful for configuration management, software installation, troubleshooting. Logs all commands in CloudTrail."},
		{ID: 128, Text: "What is AWS Systems Manager Automation?", Options: [4]string{"Operational tasks", "Runbooks", "Self-healing", "All of the above"}, CorrectAnswer: 3, Explanation: "Automation executes operational tasks and runbooks. Automate common tasks (instance refresh, AMI creation, etc.). Can be triggered manually or by events. Self-healing capabilities. Essential for operational automation. Reduces manual intervention. Enables consistent, repeatable operations."},
		{ID: 129, Text: "What is AWS OpsWorks?", Options: [4]string{"Configuration management", "Chef/Puppet", "Application stacks", "All of the above"}, CorrectAnswer: 3, Explanation: "OpsWorks is a configuration management service using Chef and Puppet. Manages application stacks and layers. Handles deployment, scaling, monitoring. Supports EC2, on-premises, hybrid. Essential for Chef/Puppet users. Provides managed Chef/Puppet servers. Simplifies configuration management at scale."},
		{ID: 130, Text: "What is AWS Service Catalog?", Options: [4]string{"Approved products", "Self-service", "Governance", "All of the above"}, CorrectAnswer: 3, Explanation: "Service Catalog provides catalog of approved IT services. Self-service provisioning. Enforces governance and compliance. Pre-approved products (CloudFormation templates). Essential for IT governance. Enables self-service while maintaining control. Reduces shadow IT and ensures compliance."},
		{ID: 131, Text: "What is AWS Marketplace?", Options: [4]string{"Third-party software", "AMI/containers/SaaS", "Software catalog", "All of the above"}, CorrectAnswer: 3, Explanation: "Marketplace is a digital catalog of software from third-party vendors. AMIs, containers, SaaS products. One-click deployment. Pay through AWS bill. Essential for finding and deploying software. Simplifies software procurement. Integrated with AWS services."},
		{ID: 132, Text: "What is AWS QuickSight?", Options: [4]string{"Business intelligence", "Dashboards", "Data visualization", "All of the above"}, CorrectAnswer: 3, Explanation: "QuickSight is a cloud-based business intelligence service. Creates interactive dashboards and visualizations. Connects to AWS data sources (S3, RDS, Redshift, etc.). Pay per user per month. Essential for data visualization. Self-service BI for business users. No infrastructure to manage."},
		{ID: 133, Text: "What is AWS Data Pipeline?", Options: [4]string{"Data workflow", "ETL service", "Scheduled tasks", "All of the above"}, CorrectAnswer: 3, Explanation: "Data Pipeline orchestrates data workflows. Moves and transforms data between AWS services and on-premises. Scheduled execution. Handles dependencies, retries, failures. Essential for data ETL workflows. Managed alternative to running ETL on EC2. Pay per pipeline execution."},
		{ID: 134, Text: "What is AWS Lake Formation?", Options: [4]string{"Data lake management", "Centralized permissions", "ETL automation", "All of the above"}, CorrectAnswer: 3, Explanation: "Lake Formation simplifies building and managing data lakes. Centralized permissions and security. Automates ETL from databases. Works with S3, Glue, Athena, Redshift. Essential for data lake governance. Simplifies data lake setup and management. Provides fine-grained access control."},
		{ID: 135, Text: "What is AWS Data Exchange?", Options: [4]string{"Data marketplace", "Third-party data", "Data subscription", "All of the above"}, CorrectAnswer: 3, Explanation: "Data Exchange is a data marketplace. Find, subscribe to, and use third-party data. Data products from various providers. Pay per subscription. Essential for accessing external data. Simplifies data acquisition. Integrated with AWS analytics services."},
		{ID: 136, Text: "What is AWS SageMaker?", Options: [4]string{"Machine learning", "ML platform", "End-to-end ML", "All of the above"}, CorrectAnswer: 3, Explanation: "SageMaker is a fully managed machine learning platform. Build, train, deploy ML models. Integrated Jupyter notebooks. Built-in algorithms. AutoML capabilities. Essential for ML workloads. Simplifies ML development and deployment. Handles infrastructure management."},
		{ID: 137, Text: "What is AWS Comprehend?", Options: [4]string{"NLP service", "Text analysis", "Sentiment analysis", "All of the above"}, CorrectAnswer: 3, Explanation: "Comprehend is a natural language processing service. Extracts insights from text. Sentiment analysis, entity recognition, language detection, key phrases. Uses machine learning. Essential for text analysis. No ML expertise required. Pay per document or character analyzed."},
		{ID: 138, Text: "What is AWS Rekognition?", Options: [4]string{"Image/video analysis", "Face detection", "Object detection", "All of the above"}, CorrectAnswer: 3, Explanation: "Rekognition analyzes images and videos using machine learning. Face detection/recognition, object detection, text detection, content moderation. API-based service. Essential for image/video analysis. No ML expertise required. Pay per image/video analyzed or per minute of video."},
		{ID: 139, Text: "What is AWS Polly?", Options: [4]string{"Text to speech", "Voice synthesis", "Multiple languages", "All of the above"}, CorrectAnswer: 3, Explanation: "Polly converts text to lifelike speech. Multiple voices and languages. Neural voices for natural sound. SSML support for control. Essential for voice applications. Pay per character. Integrates with other AWS services. Useful for accessibility and voice interfaces."},
		{ID: 140, Text: "What is AWS Transcribe?", Options: [4]string{"Speech to text", "Audio transcription", "Real-time transcription", "All of the above"}, CorrectAnswer: 3, Explanation: "Transcribe converts speech to text. Supports multiple languages and audio formats. Real-time and batch transcription. Custom vocabulary support. Essential for audio transcription. Pay per second of audio. Useful for meeting transcripts, captions, content indexing."},
		{ID: 141, Text: "What is AWS Translate?", Options: [4]string{"Language translation", "Text translation", "Real-time translation", "All of the above"}, CorrectAnswer: 3, Explanation: "Translate translates text between languages. Supports many language pairs. Neural machine translation. Real-time and batch. Custom terminology support. Essential for multilingual applications. Pay per character. Useful for content localization and translation."},
		{ID: 142, Text: "What is AWS Lex?", Options: [4]string{"Chatbot service", "Conversational AI", "Voice/text bots", "All of the above"}, CorrectAnswer: 3, Explanation: "Lex builds conversational interfaces (chatbots). Voice and text. Natural language understanding. Integrates with Lambda, Connect, mobile apps. Powers Alexa. Essential for building chatbots. Pay per request. Simplifies conversational AI development."},
		{ID: 143, Text: "What is AWS Connect?", Options: [4]string{"Contact center", "Cloud-based", "Omnichannel", "All of the above"}, CorrectAnswer: 3, Explanation: "Connect is a cloud-based contact center service. Omnichannel (voice, chat, email). Pay per minute of use. Integrates with Lex, Lambda, CRM systems. Essential for customer service. No infrastructure to manage. Scales automatically. Reduces contact center costs."},
		{ID: 144, Text: "What is AWS Chime?", Options: [4]string{"Video conferencing", "Online meetings", "Screen sharing", "All of the above"}, CorrectAnswer: 3, Explanation: "Chime is a communications service for online meetings. Video conferencing, screen sharing, chat. SDK for embedding in applications. Pay per user or per meeting. Essential for video communications. High-quality audio/video. Integrates with AWS services."},
		{ID: 145, Text: "What is AWS WorkSpaces?", Options: [4]string{"Virtual desktops", "DaaS", "Windows/Linux", "All of the above"}, CorrectAnswer: 3, Explanation: "WorkSpaces provides managed virtual desktops (DaaS). Windows or Linux. Access from anywhere. Pay monthly or hourly. Essential for remote work. Simplifies desktop management. No infrastructure to manage. Secure and scalable."},
		{ID: 146, Text: "What is AWS WorkDocs?", Options: [4]string{"Document storage", "File sharing", "Collaboration", "All of the above"}, CorrectAnswer: 3, Explanation: "WorkDocs is a secure document storage and sharing service. File versioning, comments, collaboration. Mobile apps. Integrates with Active Directory. Essential for document management. Pay per user per month. Alternative to SharePoint or Dropbox."},
		{ID: 147, Text: "What is AWS WorkLink?", Options: [4]string{"Mobile app access", "Secure web access", "No VPN", "All of the above"}, CorrectAnswer: 3, Explanation: "WorkLink provides secure mobile access to internal websites. No VPN needed. Streams content to mobile devices. Essential for mobile workforce. Simplifies secure mobile access. Pay per active user per month. Reduces VPN complexity."},
		{ID: 148, Text: "What is AWS AppStream?", Options: [4]string{"Application streaming", "Desktop apps", "No installation", "All of the above"}, CorrectAnswer: 3, Explanation: "AppStream streams desktop applications to users. No installation needed. Runs on AWS infrastructure. Pay per streaming instance hour. Essential for application delivery. Useful for graphics-intensive applications. Supports Windows applications."},
		{ID: 149, Text: "What is AWS Ground Station?", Options: [4]string{"Satellite communication", "Ground stations", "Satellite data", "All of the above"}, CorrectAnswer: 3, Explanation: "Ground Station provides satellite communication services. Control satellites, ingest satellite data. Pay per antenna-minute. Essential for satellite operations. Reduces need to build ground stations. Global network of ground stations."},
		{ID: 150, Text: "What is AWS RoboMaker?", Options: [4]string{"Robotics development", "Simulation", "ROS support", "All of the above"}, CorrectAnswer: 3, Explanation: "RoboMaker is a cloud-based robotics development platform. Simulate robots, run ROS applications. Extends ROS with cloud services. Essential for robotics development. Pay for compute and storage used. Simplifies robot simulation and testing."},
		{ID: 151, Text: "What is AWS IoT Core?", Options: [4]string{"IoT platform", "Device connectivity", "MQTT/HTTP", "All of the above"}, CorrectAnswer: 3, Explanation: "IoT Core connects IoT devices to AWS. Supports MQTT, HTTP, WebSockets. Billions of devices. Device shadows for state. Rules engine for routing. Essential for IoT applications. Pay per message. Scales to millions of devices. Integrates with Lambda, DynamoDB, S3."},
		{ID: 152, Text: "What is AWS IoT Device Management?", Options: [4]string{"Device lifecycle", "Remote management", "Fleet management", "All of the above"}, CorrectAnswer: 3, Explanation: "IoT Device Management manages IoT device fleets. Remote management, monitoring, updates. Device registry, jobs, thing groups. Essential for large IoT deployments. Simplifies device lifecycle management. Reduces operational overhead."},
		{ID: 153, Text: "What is AWS IoT Analytics?", Options: [4]string{"IoT data analysis", "Time series", "Data processing", "All of the above"}, CorrectAnswer: 3, Explanation: "IoT Analytics analyzes IoT data. Time series data processing. Data transformation, enrichment. Integrates with QuickSight. Essential for IoT insights. Pay per message analyzed. Simplifies IoT data analysis. Handles large volumes of IoT data."},
		{ID: 154, Text: "What is AWS IoT Greengrass?", Options: [4]string{"Edge computing", "Local processing", "Offline capability", "All of the above"}, CorrectAnswer: 3, Explanation: "IoT Greengrass extends AWS to edge devices. Local compute, messaging, data sync. Works offline. Lambda functions run locally. Essential for edge computing. Reduces latency and bandwidth. Enables offline operation."},
		{ID: 155, Text: "What is AWS FreeRTOS?", Options: [4]string{"Embedded OS", "Microcontroller OS", "IoT devices", "All of the above"}, CorrectAnswer: 3, Explanation: "FreeRTOS is an operating system for microcontrollers. Small, low-power devices. Connects to AWS IoT. Open source. Essential for microcontroller-based IoT devices. Reduces development time. Enables secure IoT connectivity."},
		{ID: 156, Text: "What is AWS Elemental MediaConvert?", Options: [4]string{"Video transcoding", "Format conversion", "On-demand processing", "All of the above"}, CorrectAnswer: 3, Explanation: "MediaConvert transcodes video files. Converts between formats, resolutions, bitrates. On-demand processing. Essential for video processing. Pay per minute of video. Supports many formats. Used for video-on-demand workflows."},
		{ID: 157, Text: "What is AWS Elemental MediaLive?", Options: [4]string{"Live video", "Broadcast encoding", "Real-time streaming", "All of the above"}, CorrectAnswer: 3, Explanation: "MediaLive encodes live video for broadcast and streaming. Real-time encoding. Multiple output formats. DVR functionality. Essential for live streaming. Pay per channel hour. Used for live TV, events, streaming."},
		{ID: 158, Text: "What is AWS Elemental MediaPackage?", Options: [4]string{"Video packaging", "Format preparation", "DRM support", "All of the above"}, CorrectAnswer: 3, Explanation: "MediaPackage prepares and protects video for delivery. Packaging for different devices. DRM support. Time-shifted viewing. Essential for video delivery. Pay per GB of data processed. Works with MediaLive and MediaConvert."},
		{ID: 159, Text: "What is AWS Elemental MediaStore?", Options: [4]string{"Video storage", "Low latency", "Media-optimized", "All of the above"}, CorrectAnswer: 3, Explanation: "MediaStore is storage optimized for media. Low latency for live streaming. S3-compatible API. Essential for media workflows. Pay for storage and requests. Used with MediaLive for live streaming. Optimized for media access patterns."},
		{ID: 160, Text: "What is AWS Elemental MediaTailor?", Options: [4]string{"Ad insertion", "Server-side ads", "Personalized ads", "All of the above"}, CorrectAnswer: 3, Explanation: "MediaTailor inserts server-side ads into video streams. Personalized ad insertion. Works with live and VOD. Essential for monetization. Pay per ad decision request. Increases ad revenue. Better user experience than client-side ads."},
		{ID: 161, Text: "What is AWS Kinesis Video Streams?", Options: [4]string{"Video streaming", "Real-time video", "ML integration", "All of the above"}, CorrectAnswer: 3, Explanation: "Kinesis Video Streams ingests and stores video streams. Real-time video from devices. Integrates with Rekognition, SageMaker. Essential for video analytics. Pay per GB ingested and stored. Used for security cameras, live streaming, video analytics."},
		{ID: 162, Text: "What is AWS Managed Streaming for Apache Kafka (MSK)?", Options: [4]string{"Managed Kafka", "Streaming platform", "Real-time data", "All of the above"}, CorrectAnswer: 3, Explanation: "MSK is a fully managed Apache Kafka service. Real-time streaming data platform. No infrastructure management. Auto-scaling. Essential for Kafka workloads. Pay for brokers and storage. Compatible with Kafka APIs. Simplifies Kafka operations."},
		{ID: 163, Text: "What is AWS DocumentDB?", Options: [4]string{"MongoDB compatible", "Document database", "Managed NoSQL", "All of the above"}, CorrectAnswer: 3, Explanation: "DocumentDB is a MongoDB-compatible document database. Fully managed. MongoDB API compatible. Multi-AZ, backups, monitoring. Essential for MongoDB workloads. Pay for instances and storage. Easier than self-managed MongoDB. High availability and durability."},
		{ID: 164, Text: "What is AWS Neptune?", Options: [4]string{"Graph database", "Relationship queries", "RDF/Property Graph", "All of the above"}, CorrectAnswer: 3, Explanation: "Neptune is a fully managed graph database. Optimized for relationship queries. Supports RDF and Property Graph models. Multi-AZ, backups. Essential for graph workloads. Pay for instances and storage. Used for social networks, recommendation engines, fraud detection."},
		{ID: 165, Text: "What is AWS Timestream?", Options: [4]string{"Time series database", "IoT/DevOps data", "Serverless", "All of the above"}, CorrectAnswer: 3, Explanation: "Timestream is a serverless time series database. Optimized for IoT and DevOps data. Automatic scaling. Pay for storage and queries. Essential for time series data. Much faster and cheaper than relational databases for time series. Built-in data retention policies."},
		{ID: 166, Text: "What is AWS QLDB?", Options: [4]string{"Ledger database", "Immutable ledger", "Blockchain-like", "All of the above"}, CorrectAnswer: 3, Explanation: "QLDB (Quantum Ledger Database) is a ledger database. Immutable, cryptographically verifiable. Centralized (not blockchain). Append-only. Essential for audit trails, financial records. Pay for storage and I/O. Provides complete history of changes. Verifiable and tamper-proof."},
		{ID: 167, Text: "What is AWS ElastiCache?", Options: [4]string{"In-memory cache", "Redis/Memcached", "Low latency", "All of the above"}, CorrectAnswer: 3, Explanation: "ElastiCache provides managed Redis and Memcached. In-memory caching. Reduces database load. Low latency. Essential for caching. Pay for nodes. Improves application performance. Supports clustering, replication, persistence."},
		{ID: 168, Text: "What is AWS MemoryDB?", Options: [4]string{"Redis-compatible", "Durable memory", "Primary database", "All of the above"}, CorrectAnswer: 3, Explanation: "MemoryDB is a Redis-compatible durable in-memory database. Multi-AZ with automatic failover. Microsecond latency. Can be used as primary database. Essential for ultra-fast applications. Pay for nodes and storage. Combines speed of Redis with durability."},
		{ID: 169, Text: "What is AWS DMS?", Options: [4]string{"Database migration", "Homogeneous/heterogeneous", "Continuous replication", "All of the above"}, CorrectAnswer: 3, Explanation: "DMS (Database Migration Service) migrates databases to AWS. Homogeneous (same engine) or heterogeneous (different engine). One-time migration or continuous replication. Essential for database migration. Pay for compute hours. Reduces downtime. Supports many source and target databases."},
		{ID: 170, Text: "What is AWS Database Migration Service (DMS) Schema Conversion Tool?", Options: [4]string{"Schema conversion", "Database conversion", "Automated conversion", "All of the above"}, CorrectAnswer: 3, Explanation: "Schema Conversion Tool converts database schemas. Heterogeneous migrations (e.g., Oracle to PostgreSQL). Converts schema and code. Essential for database engine migrations. Free tool. Reduces manual conversion effort. Identifies conversion issues."},
		{ID: 171, Text: "What is AWS RDS Proxy?", Options: [4]string{"Connection pooling", "Database proxy", "Serverless compatible", "All of the above"}, CorrectAnswer: 3, Explanation: "RDS Proxy is a database proxy service. Connection pooling for RDS. Reduces database connections. Serverless compatible (Lambda). Essential for serverless applications. Pay per vCPU hour. Improves scalability. Handles failover automatically."},
		{ID: 172, Text: "What is AWS Aurora Serverless?", Options: [4]string{"Auto-scaling database", "Serverless RDS", "Pay per ACU", "All of the above"}, CorrectAnswer: 3, Explanation: "Aurora Serverless automatically scales database capacity. Scales to zero when not in use. Pay per ACU (Aurora Capacity Unit) per second. Essential for variable workloads. No capacity planning needed. Cost-effective for intermittent workloads."},
		{ID: 173, Text: "What is AWS Aurora Global Database?", Options: [4]string{"Multi-region", "Global replication", "Low latency", "All of the above"}, CorrectAnswer: 3, Explanation: "Aurora Global Database spans multiple AWS regions. Replication lag < 1 second. Read replicas in multiple regions. Essential for global applications. Reduces latency for global users. Disaster recovery across regions. Up to 16 read replicas."},
		{ID: 174, Text: "What is AWS Backup for RDS?", Options: [4]string{"Automated backups", "Point-in-time recovery", "Cross-region backup", "All of the above"}, CorrectAnswer: 3, Explanation: "RDS automated backups enable point-in-time recovery. Backs up transaction logs. Retention period configurable (up to 35 days). Can copy to other regions. Essential for data protection. No additional cost (included). Enables recovery to any point in retention period."},
		{ID: 175, Text: "What is AWS RDS Read Replicas?", Options: [4]string{"Read scaling", "Asynchronous replication", "Multiple copies", "All of the above"}, CorrectAnswer: 3, Explanation: "Read Replicas are read-only copies of RDS database. Asynchronous replication. Offloads read traffic from primary. Up to 15 read replicas. Can promote to standalone. Essential for read scaling. Reduces load on primary database. Can be in different regions."},
		{ID: 176, Text: "What is AWS RDS Multi-AZ?", Options: [4]string{"High availability", "Synchronous replication", "Automatic failover", "All of the above"}, CorrectAnswer: 3, Explanation: "Multi-AZ deploys RDS in multiple Availability Zones. Synchronous replication. Automatic failover (< 60 seconds). High availability. Essential for production. No code changes needed. Increases availability to 99.95%. Protects against AZ failures."},
		{ID: 177, Text: "What is AWS RDS Snapshot?", Options: [4]string{"Manual backup", "Point-in-time copy", "Cross-region copy", "All of the above"}, CorrectAnswer: 3, Explanation: "RDS snapshots are manual point-in-time backups. Stored in S3. Can copy to other regions. Can restore to new instance. Essential for backups and migrations. Pay for storage. Retained until deleted. Useful for disaster recovery."},
		{ID: 178, Text: "What is AWS RDS Performance Insights?", Options: [4]string{"Performance monitoring", "Database metrics", "Query analysis", "All of the above"}, CorrectAnswer: 3, Explanation: "Performance Insights monitors database performance. Visualizes database load. Identifies top SQL statements. No performance impact. Essential for performance tuning. Pay per vCPU hour. Helps optimize database performance. Easy to enable."},
		{ID: 179, Text: "What is AWS RDS Enhanced Monitoring?", Options: [4]string{"OS metrics", "Detailed monitoring", "CloudWatch integration", "All of the above"}, CorrectAnswer: 3, Explanation: "Enhanced Monitoring provides OS-level metrics. CPU, memory, disk, network. More detailed than basic monitoring. CloudWatch integration. Essential for troubleshooting. Pay for CloudWatch Logs. Helps identify performance issues. Granular metrics (1-60 second intervals)."},
		{ID: 180, Text: "What is AWS RDS Event Subscription?", Options: [4]string{"Event notifications", "SNS integration", "Database events", "All of the above"}, CorrectAnswer: 3, Explanation: "Event Subscription sends notifications for RDS events. Instance creation, deletion, failover, etc. SNS integration. Essential for monitoring. Free service. Helps track database changes. Can trigger automated responses."},
		{ID: 181, Text: "What is AWS S3 Transfer Acceleration?", Options: [4]string{"Faster uploads", "CloudFront edge", "Long distances", "All of the above"}, CorrectAnswer: 3, Explanation: "Transfer Acceleration uses CloudFront edge locations for faster S3 uploads. Optimized path to S3. Reduces latency for long distances. Essential for global uploads. Pay for acceleration and data transfer. Can improve upload speed significantly. Uses edge network."},
		{ID: 182, Text: "What is AWS S3 Multipart Upload?", Options: [4]string{"Large files", "Parallel upload", "Resumable", "All of the above"}, CorrectAnswer: 3, Explanation: "Multipart Upload splits large files into parts. Uploads parts in parallel. Resumable if part fails. Essential for files > 5GB. More reliable than single upload. Faster for large files. Each part can be up to 5GB."},
		{ID: 183, Text: "What is AWS S3 Byte-Range Fetches?", Options: [4]string{"Partial downloads", "Range requests", "Efficient retrieval", "All of the above"}, CorrectAnswer: 3, Explanation: "Byte-Range Fetches download specific byte ranges of objects. HTTP Range requests. Essential for partial downloads, video streaming, resuming downloads. More efficient than downloading entire object. Supports multiple ranges in single request."},
		{ID: 184, Text: "What is AWS S3 Object Lock?", Options: [4]string{"WORM storage", "Immutable objects", "Compliance", "All of the above"}, CorrectAnswer: 3, Explanation: "Object Lock prevents object deletion or overwriting. WORM (Write Once Read Many). Governance mode (can be overridden) or Compliance mode (cannot be overridden). Essential for compliance. Retention periods. Legal holds. Protects against accidental or malicious deletion."},
		{ID: 185, Text: "What is AWS S3 Inventory?", Options: [4]string{"Object listing", "Metadata reports", "Compliance auditing", "All of the above"}, CorrectAnswer: 3, Explanation: "S3 Inventory provides scheduled reports of objects. Lists objects and metadata. CSV, ORC, Parquet formats. Essential for auditing, compliance, analytics. Can filter by prefix, tags. Delivered to S3 bucket. Helps manage large buckets."},
		{ID: 186, Text: "What is AWS S3 Analytics?", Options: [4]string{"Storage analysis", "Access patterns", "Optimization", "All of the above"}, CorrectAnswer: 3, Explanation: "S3 Analytics analyzes storage access patterns. Recommends lifecycle policies. Identifies infrequently accessed objects. Essential for cost optimization. Free service. Helps optimize storage costs. Data-driven lifecycle decisions."},
		{ID: 187, Text: "What is AWS S3 Batch Operations?", Options: [4]string{"Bulk operations", "Large-scale changes", "Copy/tag/delete", "All of the above"}, CorrectAnswer: 3, Explanation: "Batch Operations performs large-scale operations on S3 objects. Copy, invoke Lambda, restore from Glacier, etc. Processes millions of objects. Essential for bulk changes. Pay per operation. More efficient than individual API calls. Handles failures automatically."},
		{ID: 188, Text: "What is AWS S3 Object Lambda?", Options: [4]string{"Transform objects", "On-the-fly processing", "Lambda integration", "All of the above"}, CorrectAnswer: 3, Explanation: "Object Lambda uses Lambda to transform objects on-the-fly. Modify data as it's retrieved. No need to store multiple copies. Essential for data transformation. Pay for Lambda execution and data transfer. Useful for filtering, redacting, converting formats."},
		{ID: 189, Text: "What is AWS S3 Access Points?", Options: [4]string{"Shared access", "Delegated access", "VPC endpoints", "All of the above"}, CorrectAnswer: 3, Explanation: "Access Points provide shared access to S3 buckets. Unique hostname per access point. Different permissions per access point. Essential for multi-tenant applications. Simplifies access management. Can restrict by VPC, IP, IAM. Reduces bucket policy complexity."},
		{ID: 190, Text: "What is AWS S3 Multi-Region Access Points?", Options: [4]string{"Global endpoints", "Multi-region routing", "Active-active", "All of the above"}, CorrectAnswer: 3, Explanation: "Multi-Region Access Points provide global endpoints for S3. Routes to nearest region automatically. Active-active setup. Reduces latency. Essential for global applications. Improves availability. Single endpoint for multiple regions."},
		{ID: 191, Text: "What is AWS S3 Intelligent-Tiering?", Options: [4]string{"Automatic optimization", "Cost savings", "Access pattern learning", "All of the above"}, CorrectAnswer: 3, Explanation: "Intelligent-Tiering automatically moves objects between access tiers. Monitors access patterns. No retrieval fees. Small monitoring fee per object. Essential for unknown access patterns. Optimizes costs automatically. Four access tiers: Frequent, Infrequent, Archive, Deep Archive."},
		{ID: 192, Text: "What is AWS S3 Glacier Instant Retrieval?", Options: [4]string{"Archive storage", "Millisecond access", "Low cost", "All of the above"}, CorrectAnswer: 3, Explanation: "Glacier Instant Retrieval provides archive storage with millisecond retrieval. Lower cost than Standard-IA. For rarely accessed data needing instant access. Essential for archive with instant access needs. Cheaper than Standard-IA for long-term storage."},
		{ID: 193, Text: "What is AWS S3 Glacier Flexible Retrieval?", Options: [4]string{"Archive storage", "3 retrieval options", "Low cost", "All of the above"}, CorrectAnswer: 3, Explanation: "Glacier Flexible Retrieval (formerly Glacier) provides low-cost archive storage. Three retrieval options: Expedited (1-5 min), Standard (3-5 hours), Bulk (5-12 hours). Essential for long-term archives. Cheapest option for infrequent access. Retrieval fees apply."},
		{ID: 194, Text: "What is AWS S3 Glacier Deep Archive?", Options: [4]string{"Lowest cost", "Long-term archive", "12-hour retrieval", "All of the above"}, CorrectAnswer: 3, Explanation: "Glacier Deep Archive is the lowest-cost storage class. 12-hour retrieval time. Essential for long-term archives, compliance data. Cheapest storage option. Retrieval takes 12 hours. Suitable for data rarely accessed."},
		{ID: 195, Text: "What is AWS S3 Requester Pays?", Options: [4]string{"Cost transfer", "Data requester pays", "Bucket owner exemption", "All of the above"}, CorrectAnswer: 3, Explanation: "Requester Pays makes the requester pay for data transfer and requests. Bucket owner pays only for storage. Essential for sharing large datasets. Reduces costs for data providers. Requesters need appropriate permissions."},
		{ID: 196, Text: "What is AWS S3 Presigned URLs?", Options: [4]string{"Temporary access", "Time-limited", "No IAM needed", "All of the above"}, CorrectAnswer: 3, Explanation: "Presigned URLs provide temporary access to S3 objects. Time-limited (expires). No IAM credentials needed for requester. Essential for sharing private objects. Generated by bucket owner. Useful for downloads, uploads. Expires after specified time."},
		{ID: 197, Text: "What is AWS S3 CORS?", Options: [4]string{"Cross-origin access", "Web browser access", "CORS headers", "All of the above"}, CorrectAnswer: 3, Explanation: "CORS (Cross-Origin Resource Sharing) allows web browsers to access S3 from different domains. Configures allowed origins, methods, headers. Essential for web applications accessing S3. Prevents unauthorized cross-origin access. Configured via bucket CORS policy."},
		{ID: 198, Text: "What is AWS S3 Website Hosting?", Options: [4]string{"Static website", "HTTP hosting", "Index/error pages", "All of the above"}, CorrectAnswer: 3, Explanation: "S3 can host static websites. Configure index and error documents. Public read access needed. Essential for static websites. Low cost. Integrates with CloudFront for CDN. No servers to manage."},
		{ID: 199, Text: "What is AWS S3 MFA Delete?", Options: [4]string{"Extra protection", "MFA for deletion", "Version protection", "All of the above"}, CorrectAnswer: 3, Explanation: "MFA Delete requires MFA to delete object versions or change versioning state. Extra protection for important data. Essential for compliance. Prevents accidental or malicious deletion. Only root account can enable. Adds security layer."},
		{ID: 200, Text: "What is AWS S3 Server Access Logging?", Options: [4]string{"Access logs", "Audit trail", "Request logging", "All of the above"}, CorrectAnswer: 3, Explanation: "Server Access Logging logs all requests to S3 bucket. Detailed access information. Stored in another S3 bucket. Essential for auditing and security. Helps track access patterns. Useful for compliance. Can analyze with Athena."},
	})
}
